def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            comps.append({
                "color": color, "cells": cells,
                "minr": min(rs), "maxr": max(rs),
                "minc": min(cs), "maxc": max(cs)
            })

    # The guide object is the colored component touching two adjacent
    # borders, forming an L-like marker.
    guides = []
    for o in comps:
        edges = set()
        if o["minr"] == 0: edges.add("top")
        if o["maxr"] == h - 1: edges.add("bottom")
        if o["minc"] == 0: edges.add("left")
        if o["maxc"] == w - 1: edges.add("right")
        if len(edges) >= 2:
            guides.append(o)

    if not guides:
        return out
    guide = min(guides, key=lambda o: len(o["cells"]))

    candidates = [o for o in comps if o is not guide and o["color"] != guide["color"]]
    if not candidates:
        return out

    def distance(obj):
        return min(abs(y - a) + abs(x - b)
                   for y, x in obj["cells"] for a, b in guide["cells"])

    target = min(candidates, key=distance)
    for y, x in target["cells"]:
        out[y][x] = guide["color"]
    return out
